1	//! `Vec<Item>` → Bedrock Converse `Message` / `SystemContentBlock` translation.
2	//!
3	//! Rules per SMA-329 spec §6 "Wire translation":
4	//! - `Item::System` → `SystemContentBlock::Text`; system blocks are never mixed
5	//!   into the `messages` slice.
6	//! - Blank text (empty or whitespace-only) is never sent: Converse rejects it.
7	//!   A dropped block leaves no placeholder. An `Item::System` with only blank
8	//!   text adds no system block.
9	//! - Adjacent same-role turns are joined into one turn.
10	//! - `Item::ToolCall` / `ContentPart::ToolUse` → `ContentBlock::ToolUse` on
11	//!   the assistant turn.
12	//! - `Item::ToolResult` queued pending → flushed as `ContentBlock::ToolResult`
13	//!   blocks prepended to the next user turn.
14	//! - No message with content after blank text is dropped → error.
15	
16	use aws_sdk_bedrockruntime::types::{
17	    ContentBlock, ConversationRole, Message, SystemContentBlock, ToolResultBlock,
18	    ToolResultContentBlock, ToolUseBlock,
19	};
20	use paigasus_helikon_core::{ContentPart, Item, ModelError};
21	#[cfg(test)]
22	use serde_json::{json, Value};
23	
24	use crate::document::value_to_document;
25	
26	/// Output of [`items_to_messages`].
27	#[derive(Debug)]
28	pub(crate) struct TranslatedMessages {
29	    /// System prompt blocks (`SystemContentBlock::Text`) extracted from
30	    /// `Item::System` entries.
31	    pub(crate) system: Vec<SystemContentBlock>,
32	    /// Conversation turns. Adjacent same-role turns are joined.
33	    pub(crate) messages: Vec<Message>,
34	}
35	
36	/// Translate the conversation into Bedrock Converse `Message`s.
37	///
38	/// Returns an error when no message with content remains. Empty or
39	/// whitespace-only text and unsupported parts are not sent. Also returns an
40	/// error when the last user message had only empty or whitespace-only text and
41	/// the request would then end with an assistant message.
42	pub(crate) fn items_to_messages(items: &[Item]) -> Result<TranslatedMessages, ModelError> {
43	    let mut system: Vec<SystemContentBlock> = Vec::new();
44	    let mut messages: Vec<Message> = Vec::new();
45	
46	    // Pending assistant-side content blocks (ToolUse / Text for an assistant turn
47	    // that hasn't been flushed yet).
48	    let mut pending_assistant: Vec<ContentBlock> = Vec::new();
49	    // Pending ToolResult blocks to prepend to the next user turn.
50	    let mut pending_tool_results: Vec<ContentBlock> = Vec::new();
51	    // `true` when the latest user message had blank text and produced no
52	    // block. Dropping it could leave the request ending with an assistant turn.
53	    let mut last_user_dropped = false;
54	
55	    /// Flush `pending_assistant` into an assistant Message on `messages`.
56	    ///
57	    /// If the last message is already an assistant turn, the pending content
58	    /// blocks are appended to it (coalescing) rather than creating a new turn.
59	    fn flush_assistant(messages: &mut Vec<Message>, pending: &mut Vec<ContentBlock>) {
60	        if !pending.is_empty() {
61	            let content = std::mem::take(pending);
62	            if messages
63	                .last()
64	                .map(|m| m.role == ConversationRole::Assistant)
65	                .unwrap_or(false)
66	            {
67	                // Coalesce: append to the existing assistant turn.
68	                let last = messages.last_mut().unwrap();
69	                last.content.extend(content);
70	            } else {
71	                let msg = Message::builder()
72	                    .role(ConversationRole::Assistant)
73	                    .set_content(Some(content))
74	                    .build()
75	                    .expect("role + non-empty content always valid");
76	                messages.push(msg);
77	            }
78	        }
79	    }
80	
81	    /// Flush `pending_tool_results` into a user Message on `messages`.
82	    ///
83	    /// If the last message is already a user turn, the results are appended to
84	    /// it (coalescing) rather than creating a new turn.
85	    fn flush_user_results(messages: &mut Vec<Message>, pending: &mut Vec<ContentBlock>) {
86	        if !pending.is_empty() {
87	            let content = std::mem::take(pending);
88	            if messages
89	                .last()
90	                .map(|m| m.role == ConversationRole::User)
91	                .unwrap_or(false)
92	            {
93	                let last = messages.last_mut().unwrap();
94	                last.content.extend(content);
95	            } else {
96	                let msg = Message::builder()
97	                    .role(ConversationRole::User)
98	                    .set_content(Some(content))
99	                    .build()
100	                    .expect("role + non-empty content always valid");
101	                messages.push(msg);
102	            }
103	        }
104	    }
105	
106	    for item in items {
107	        match item {
108	            Item::System { content } => {
109	                // System items are pulled out to the `system` slot; flush any
110	                // in-progress turns first so ordering is preserved.
111	                flush_assistant(&mut messages, &mut pending_assistant);
112	                flush_user_results(&mut messages, &mut pending_tool_results);
113	                let text = text_of(content);
114	                if !is_blank(&text) {
115	                    system.push(SystemContentBlock::Text(text));
116	                }
117	            }
118	
119	            Item::UserMessage { content } => {
120	                flush_assistant(&mut messages, &mut pending_assistant);
121	                // Pending tool results precede any user text in this turn.
122	                let mut blocks: Vec<ContentBlock> = std::mem::take(&mut pending_tool_results);
123	                let mut had_blank_text = false;
124	                for part in content {
125	                    match part {
126	                        ContentPart::Text { text } => {
127	                            if is_blank(text) {
128	                                had_blank_text = true;
129	                            } else {
130	                                blocks.push(ContentBlock::Text(text.clone()));
131	                            }
132	                        }
133	                        ContentPart::ToolResult { call_id, content } => {
134	                            // Native Anthropic-shaped ToolResult inside a UserMessage.
135	                            let result_block = build_tool_result_block(call_id, content);
136	                            blocks.push(ContentBlock::ToolResult(result_block));
137	                        }
138	                        _ => {
139	                            tracing::warn!(
140	                                target: "paigasus::bedrock::translate",
141	                                "unsupported ContentPart variant in UserMessage; skipping",
142	                            );
143	                        }
144	                    }
145	                }
146	                last_user_dropped = had_blank_text && blocks.is_empty();
147	                if !blocks.is_empty() {
148	                    if messages
149	                        .last()
150	                        .map(|m| m.role == ConversationRole::User)
151	                        .unwrap_or(false)
152	                    {
153	                        // Coalesce: append to the existing user turn.
154	                        let last = messages.last_mut().unwrap();
155	                        last.content.extend(blocks);
156	                    } else {
157	                        let msg = Message::builder()
158	                            .role(ConversationRole::User)
159	                            .set_content(Some(blocks))
160	                            .build()
161	                            .expect("role + non-empty content always valid");
162	                        messages.push(msg);
163	                    }
164	                }
165	            }
166	
167	            Item::AssistantMessage { content, .. } => {
168	                let mut blocks: Vec<ContentBlock> = Vec::new();
169	                for part in content {
170	                    match part {
171	                        ContentPart::Text { text } => {
172	                            if !is_blank(text) {
173	                                blocks.push(ContentBlock::Text(text.clone()));
174	                            }
175	                        }
176	                        ContentPart::ToolUse {
177	                            call_id,
178	                            name,
179	                            args,
180	                        } => {
181	                            let tool_use = ToolUseBlock::builder()
182	                                .tool_use_id(call_id)
183	                                .name(name)
184	                                .input(value_to_document(args))
185	                                .build()
186	                                .expect("tool_use_id + name + input always valid");
187	                            blocks.push(ContentBlock::ToolUse(tool_use));
188	                        }
189	                        ContentPart::Reasoning { .. } => {
190	                            tracing::warn!(
191	                                target: "paigasus::bedrock::translate",
192	                                "dropping ContentPart::Reasoning — round-trip not supported on Bedrock",
193	                            );
194	                        }
195	                        _ => {
196	                            tracing::warn!(
197	                                target: "paigasus::bedrock::translate",
198	                                "unsupported ContentPart variant in AssistantMessage; skipping",
199	                            );
200	                        }
201	                    }
202	                }
203	                // An assistant item with no blocks acts as if it were absent:
204	                // it flushes nothing, so an open tool round stays whole.
205	                //
206	                // A message made only of tool uses is the nested form of
207	                // `Item::ToolCall`. Inside an open round (results pending,
208	                // not all calls answered) it joins that round, as a call
209	                // does. A flush would put a user turn that lacks some
210	                // results right after the open assistant turn.
211	                if !blocks.is_empty()
212	                    && blocks.iter().all(|b| matches!(b, ContentBlock::ToolUse(_)))
213	                    && !pending_tool_results.is_empty()
214	                    && !round_is_answered(&messages, &pending_tool_results)
215	                {
216	                    last_user_dropped = false;
217	                    pending_assistant.extend(blocks);
218	                } else if !blocks.is_empty() {
219	                    last_user_dropped = false;
220	                    // Queued calls go first, then the results that answer them.
221	                    flush_assistant(&mut messages, &mut pending_assistant);
222	                    flush_user_results(&mut messages, &mut pending_tool_results);
223	                    if messages
224	                        .last()
225	                        .map(|m| m.role == ConversationRole::Assistant)
226	                        .unwrap_or(false)
227	                    {
228	                        // Coalesce: append to the existing assistant turn.
229	                        let last = messages.last_mut().unwrap();
230	                        last.content.extend(blocks);
231	                    } else {
232	                        let msg = Message::builder()
233	                            .role(ConversationRole::Assistant)
234	                            .set_content(Some(blocks))
235	                            .build()
236	                            .expect("role + non-empty content always valid");
237	                        messages.push(msg);
238	                    }
239	                }
240	            }
241	
242	            Item::ToolCall {
243	                call_id,
244	                name,
245	                args,
246	            } => {
247	                last_user_dropped = false;
248	                // A new call follows results already seen. Close that user
249	                // turn only when the last assistant round is fully answered;
250	                // otherwise the call joins that round.
251	                if !pending_tool_results.is_empty()
252	                    && round_is_answered(&messages, &pending_tool_results)
253	                {
254	                    flush_user_results(&mut messages, &mut pending_tool_results);
255	                }
256	                // Queue onto the pending assistant turn (flushed when a user
257	                // turn / system / end-of-input is encountered).
258	                let tool_use = ToolUseBlock::builder()
259	                    .tool_use_id(call_id)
260	                    .name(name)
261	                    .input(value_to_document(args))
262	                    .build()
263	                    .expect("tool_use_id + name + input always valid");
264	                pending_assistant.push(ContentBlock::ToolUse(tool_use));
265	            }
266	
267	            Item::ToolResult { call_id, content } => {
268	                last_user_dropped = false;
269	                // Flush the preceding assistant turn that requested this result.
270	                flush_assistant(&mut messages, &mut pending_assistant);
271	                // Queue onto pending user / tool-result turn.
272	                let result_block = build_tool_result_block(call_id, content);
273	                pending_tool_results.push(ContentBlock::ToolResult(result_block));
274	            }
275	
276	            _ => {
277	                tracing::warn!(
278	                    target: "paigasus::bedrock::translate",
279	                    "unknown Item variant; skipping",
280	                );
281	            }
282	        }
283	    }
284	
285	    // Flush any remaining pending content.
286	    flush_assistant(&mut messages, &mut pending_assistant);
287	    flush_user_results(&mut messages, &mut pending_tool_results);
288	
289	    // Guard: nothing to send.
290	    if messages.is_empty() {
291	        return Err(ModelError::Other(anyhow::anyhow!(
292	            "no message with content to send (empty or whitespace-only text and unsupported parts are not sent)"
293	        )));
294	    }
295	
296	    // Guard: a dropped blank user message must not leave the request ending
297	    // with an assistant turn. Converse would treat that as a prefill.
298	    if last_user_dropped
299	        && messages
300	            .last()
301	            .is_some_and(|m| m.role == ConversationRole::Assistant)
302	    {
303	        return Err(ModelError::Other(anyhow::anyhow!(
304	            "the last user message had only empty or whitespace-only text, which is not sent; the request would end with an assistant message"
305	        )));
306	    }
307	
308	    Ok(TranslatedMessages { system, messages })
309	}
310	
311	// ── Helpers ───────────────────────────────────────────────────────────────────
312	
313	/// `true` when `text` is empty or only whitespace. Converse rejects such blocks.
314	fn is_blank(text: &str) -> bool {
315	    text.trim().is_empty()
316	}
317	
318	/// `true` when every `ToolUse` id in the trailing run of assistant messages
319	/// has a matching `ToolResult` in `results`. Converse joins adjacent assistant
320	/// messages into one turn, so the whole run is one round. Also `true` when the
321	/// last message is not an assistant message, so the results then flush as
322	/// before.
323	fn round_is_answered(messages: &[Message], results: &[ContentBlock]) -> bool {
324	    messages
325	        .iter()
326	        .rev()
327	        .take_while(|m| m.role == ConversationRole::Assistant)
328	        .flat_map(|m| m.content.iter())
329	        .filter_map(|b| match b {
330	            ContentBlock::ToolUse(tu) => Some(tu.tool_use_id.as_str()),
331	            _ => None,
332	        })
333	        .all(|id| {
334	            results.iter().any(|r| match r {
335	                ContentBlock::ToolResult(tr) => tr.tool_use_id == id,
336	                _ => false,
337	            })
338	        })
339	}
340	
341	/// Extract and concatenate all text from a `Vec<ContentPart>`.
342	fn text_of(parts: &[ContentPart]) -> String {
343	    let mut s = String::new();
344	    for p in parts {
345	        if let ContentPart::Text { text } = p {
346	            if !s.is_empty() {
347	                s.push('\n');
348	            }
349	            s.push_str(text);
350	        }
351	    }
352	    s
353	}
354	
355	/// Build a `ToolResultBlock` from a call_id + content.
356	fn build_tool_result_block(call_id: &str, content: &[ContentPart]) -> ToolResultBlock {
357	    let text = text_of(content);
358	    ToolResultBlock::builder()
359	        .tool_use_id(call_id)
360	        .content(ToolResultContentBlock::Text(text))
361	        .build()
362	        .expect("tool_use_id + content always valid")
363	}
364	
365	// ── Wire-projection helper (for snapshot tests) ───────────────────────────────
366	
367	/// Project [`TranslatedMessages`] into a stable [`serde_json::Value`] for
368	/// snapshot tests. The projection is independent of SDK `Debug` output.
369	#[cfg(test)]
370	pub(crate) fn messages_to_wire_json(tm: &TranslatedMessages) -> Value {
371	    let system: Vec<Value> = tm
372	        .system
373	        .iter()
374	        .map(|s| match s {
375	            SystemContentBlock::Text(t) => json!({"type": "text", "text": t}),
376	            _ => json!({"type": "unknown"}),
377	        })
378	        .collect();
379	
380	    let messages: Vec<Value> = tm
381	        .messages
382	        .iter()
383	        .map(|m| {
384	            let role = match m.role {
385	                ConversationRole::User => "user",
386	                ConversationRole::Assistant => "assistant",
387	                _ => "unknown",
388	            };
389	            let content: Vec<Value> = m
390	                .content
391	                .iter()
392	                .map(|b| match b {
393	                    ContentBlock::Text(t) => json!({"type": "text", "text": t}),
394	                    ContentBlock::ToolUse(tu) => json!({
395	                        "type": "tool_use",
396	                        "toolUseId": tu.tool_use_id,
397	                        "name": tu.name,
398	                    }),
399	                    ContentBlock::ToolResult(tr) => {
400	                        let result_text = tr
401	                            .content
402	                            .iter()
403	                            .find_map(|c| {
404	                                if let ToolResultContentBlock::Text(t) = c {
405	                                    Some(t.as_str())
406	                                } else {
407	                                    None
408	                                }
409	                            })
410	                            .unwrap_or("");
411	                        json!({
412	                            "type": "tool_result",
413	                            "toolUseId": tr.tool_use_id,
414	                            "content": result_text,
415	                        })
416	                    }
417	                    _ => json!({"type": "unknown"}),
418	                })
419	                .collect();
420	            json!({"role": role, "content": content})

