1	//! Translation between Paigasus carrier types and Anthropic wire format.
2	
3	pub(crate) mod cache;
4	pub(crate) mod request;
5	pub(crate) mod response_format;
6	pub(crate) mod tools;
7	
8	use paigasus_helikon_core::{ModelError, ModelRequest, ToolChoice};
9	use serde_json::{json, Value};
10	
11	use crate::builder::Config;
12	use crate::settings::ExtendedThinking;
13	use response_format::{
14	    synthesize_for_response_format, validate_conflict, validate_tool_names, Synthesized,
15	};
16	
17	/// Built request body + whether the stream translator should be in synthesis mode.
18	#[derive(Debug)]
19	pub(crate) struct PreparedRequest {
20	    pub(crate) body: Value,
21	    pub(crate) synthesizing_output: bool,
22	}
23	
24	/// Build the JSON request body from the caller's `ModelRequest` plus the
25	/// builder-baked `Config`. Runs all synchronous validation guards.
26	pub(crate) fn build_body(cfg: &Config, req: &ModelRequest) -> Result<PreparedRequest, ModelError> {
27	    validate_tool_names(&req.tools).map_err(|m| ModelError::Other(anyhow::anyhow!(m)))?;
28	    validate_conflict(
29	        req.model_settings.response_format.as_ref(),
30	        req.model_settings.tool_choice.as_ref(),
31	    )
32	    .map_err(|m| ModelError::Other(anyhow::anyhow!(m)))?;
33	
34	    let translated = request::translate_messages(&req.messages);
35	    if translated.messages.as_array().is_none_or(|a| a.is_empty()) {
36	        return Err(ModelError::Other(anyhow::anyhow!(
37	            "no message with content to send (empty or whitespace-only text and unsupported parts are not sent)"
38	        )));
39	    }
40	    if translated.trailing_message_dropped {
41	        return Err(ModelError::Other(anyhow::anyhow!(
42	            "the last message has no content to send (empty or whitespace-only text and unsupported parts are not sent); the request would end with an assistant message"
43	        )));
44	    }
45	
46	    let mut tools_array = tools::translate_tools(&req.tools);
47	
48	    let Synthesized {
49	        tool,
50	        tool_choice,
51	        synthesizing,
52	    } = synthesize_for_response_format(req.model_settings.response_format.as_ref());
53	    if let Some(extra) = tool {
54	        if let Some(arr) = tools_array.as_array_mut() {
55	            arr.push(extra);
56	        }
57	    }
58	
59	    let mut messages = translated.messages;
60	    let system = cache::apply_cache_strategy(
61	        cfg.cache_strategy,
62	        translated.system,
63	        &mut tools_array,
64	        &mut messages,
65	    );
66	
67	    let mut body = serde_json::Map::new();
68	    body.insert("model".into(), Value::String(cfg.model_id.clone()));
69	    body.insert("stream".into(), Value::Bool(true));
70	    body.insert("messages".into(), messages);
71	    body.insert(
72	        "max_tokens".into(),
73	        Value::Number(
74	            req.model_settings
75	                .max_output_tokens
76	                .map(|m| m.into())
77	                .unwrap_or_else(|| cfg.max_output_default.into()),
78	        ),
79	    );
80	    if let Some(s) = system {
81	        body.insert("system".into(), s);
82	    }
83	    if tools_array
84	        .as_array()
85	        .map(|a| !a.is_empty())
86	        .unwrap_or(false)
87	    {
88	        body.insert("tools".into(), tools_array);
89	    }
90	
91	    // tool_choice: synthesis overrides caller; otherwise translate caller's preference.
92	    let tc_value = match tool_choice {
93	        Some(v) => Some(v),
94	        None => req
95	            .model_settings
96	            .tool_choice
97	            .as_ref()
